1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Canonicalises a raw postal address entry into its normalized form.
7	 *
8	 * <p>Rules: trim leading/trailing whitespace, collapse internal runs of whitespace to a single
9	 * space, upper-case, and expand common street-type abbreviations token-by-token
10	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). An address that is empty or
11	 * whitespace-only normalizes to the empty string.
12	 *
13	 * <p>The conversion is idempotent — feeding an already-normalized value back in returns it
14	 * unchanged — so it can normalize both incoming requests and already-stored values for
15	 * comparison (household duplicate detection and the shared household id).
16	 */
17	final class AddressNormalizer {
18	
19	    private AddressNormalizer() {
20	    }
21	
22	    /**
23	     * @param raw the raw address text (may be {@code null})
24	     * @return the normalized address, or {@code ""} when {@code raw} is blank after normalization
25	     */
26	    static String normalize(String raw) {
27	        if (raw == null) {
28	            return "";
29	        }
30	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder result = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                result.append(' ');
39	            }
40	            result.append(expand(tokens[i]));
41	        }
42	        return result.toString();
43	    }
44	
45	    private static String expand(String token) {
46	        switch (token) {
47	            case "ST":
48	                return "STREET";
49	            case "RD":
50	                return "ROAD";
51	            case "AVE":
52	                return "AVENUE";
53	            default:
54	                return token;
55	        }
56	    }
57	}
