3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Normalizes the create-owner address: trims and collapses whitespace, upper-cases and expands
8	 * common street-type abbreviations ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
9	 * Mutates the published request in place so later steps store and return the normalized value, and
10	 * so household duplicate detection and the shared household id compare the normalized form.
11	 *
12	 * <p>{@link ValidateOwnerFields} has already rejected an address that is blank after normalization,
13	 * so at this point the value normalizes to a non-empty string.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    public void service(@Val OwnerFieldsDto request) {
18	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
19	    }
20	}
