3	/**
4	 * Pipeline variable carrying the stable shared household identifier assigned by
5	 * {@link DetermineOwnerHousehold} to {@link AssignOwnerHousehold}. A dedicated type
6	 * (rather than a bare {@code String}) keeps the variable unambiguous by type.
7	 */
8	public record HouseholdId(String value) {
9	}
