1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (canonical region) by preferring the postcode
7	 * range, then falling back to a fixed city-to-region table.
8	 *
9	 * <p>Deliberately a plain utility class rather than a method on {@link OwnerMapper}:
10	 * a {@code String -> String} method declared on a MapStruct {@code @Mapper} interface
11	 * would be picked up as a general property-conversion method and silently applied to
12	 * every string field. Kept here, it is only ever invoked from an explicit mapping
13	 * expression, so MapStruct never treats it as a conversion.
14	 */
15	public final class LocalityLookup {
16	
17	    /** City -> canonical region; anything absent derives locality "UNKNOWN". */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {low, high}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	            "NSW", new int[] {2000, 2099},
24	            "VIC", new int[] {3000, 3099},
25	            "QLD", new int[] {4000, 4099});
26	
27	    /** Region -> IANA timezone name; anything absent (e.g. "UNKNOWN") has no timezone. */
28	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
29	            "NSW", "Australia/Sydney",
30	            "VIC", "Australia/Melbourne",
31	            "QLD", "Australia/Brisbane");
32	
33	    private LocalityLookup() {
34	    }
35	
36	    /**
37	     * @param region the canonical region (e.g. "NSW")
38	     * @return the IANA timezone name for {@code region}, or {@code null} when the region
39	     *         is {@code null} or not in the fixed region-to-timezone table
40	     */
41	    public static String timezoneFor(String region) {
42	        return region == null ? null : REGION_TIMEZONE.get(region);
43	    }
44	
45	    /**
46	     * @param city the owner's city (may be {@code null})
47	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is not
48	     *         in the table
49	     */
50	    public static String regionFor(String city) {
51	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
52	    }
53	
54	    /**
55	     * Derives the canonical region, preferring the postcode: when {@code postcode} is a
56	     * 4-digit value inside a known region range (NSW 2000-2099, VIC 3000-3099,
57	     * QLD 4000-4099) that region wins, disambiguating cities that share a name.
58	     * Otherwise — postcode absent or in no known range — falls back to the
59	     * city-to-region table.
60	     *
61	     * @param city the owner's city (may be {@code null})
62	     * @param postcode the owner's postcode (may be {@code null}/blank)
63	     * @return the canonical region, or {@code "UNKNOWN"} when neither source resolves one
64	     */
65	    public static String regionFor(String city, String postcode) {
66	        String byPostcode = regionForPostcode(postcode);
67	        return byPostcode != null ? byPostcode : regionFor(city);
68	    }
69	
70	    /**
71	     * Derives the canonical region purely from the postcode, as used by the owner's
72	     * {@code <REGION>-<HASH8>} customer code. A 4-digit postcode inside a known region range
73	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) yields that region; anything else —
74	     * postcode absent, not 4 digits, or in no known range — yields {@code "UNKNOWN"}.
75	     *
76	     * @param postcode the owner's postcode (may be {@code null}/blank)
77	     * @return the canonical region for {@code postcode}, or {@code "UNKNOWN"}
78	     */
79	    public static String postcodeRegion(String postcode) {
80	        String region = regionForPostcode(postcode);
81	        return region != null ? region : "UNKNOWN";
82	    }
83	
84	    /**
85	     * @return the region whose range contains {@code postcode}, or {@code null} when the
86	     *         postcode is absent, not 4 digits, or in no known range
87	     */
88	    private static String regionForPostcode(String postcode) {
89	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
90	            return null;
91	        }
92	        int value = Integer.parseInt(postcode);
93	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
94	            int[] range = entry.getValue();
95	            if (value >= range[0] && value <= range[1]) {
96	                return entry.getKey();
97	            }
98	        }
99	        return null;
100	    }
101	}
