1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public abstract class OwnerMapper {
25	
26	    /**
27	     * Used to size the owner's household (the number of owners sharing the same
28	     * {@code householdId}) when scoring membership points. Field-injected so the
29	     * MapStruct-generated subclass, a Spring bean, receives it. May be {@code null} when the
30	     * mapper is used outside a Spring context; the household factor then scores nothing.
31	     */
32	    @Autowired
33	    protected OwnerRepository ownerRepository;
34	
35	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
36	    @Mapping(target = "displayName",
37	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
38	    @Mapping(target = "initials",
39	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
40	                    + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
41	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
42	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
43	    @Mapping(target = "locality", expression = "java(locality(owner))")
44	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
45	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
46	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
47	    @Mapping(target = "identityKey",
48	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.forOwner(owner))")
49	    @Mapping(target = "telephoneDisplay",
50	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
51	    public abstract OwnerDto toOwnerDto(Owner owner);
52	
53	    public abstract Owner toOwner(OwnerDto ownerDto);
54	
55	    @Mapping(target = "id", ignore = true)
56	    @Mapping(target = "pets", ignore = true)
57	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
58	
59	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
60	
61	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
62	
63	    /**
64	     * Scores the owner's membership points. Starts at 0; add 2 when an email address is on
65	     * file; add 1 when the owner is the first with their name ({@code namesakeCount} is 0);
66	     * add 2 for a household of 3 or more members; add 3 once the owner's tenure exceeds 365
67	     * days.
68	     */
69	    protected Integer membershipPoints(Owner owner) {
70	        int points = 0;
71	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
72	            points += 2;
73	        }
74	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
75	            points += 1;
76	        }
77	        if (householdSize(owner) >= 3) {
78	            points += 2;
79	        }
80	        if (tenureDays(owner) > 365) {
81	            points += 3;
82	        }
83	        return points;
84	    }
85	
86	    /**
87	     * Bands {@link #membershipPoints(Owner)} into the numeric membership level: 1 for 0-1
88	     * points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
89	     */
90	    protected Integer membershipLevel(Owner owner) {
91	        int points = membershipPoints(owner);
92	        if (points <= 1) {
93	            return 1;
94	        }
95	        if (points <= 3) {
96	            return 2;
97	        }
98	        if (points <= 5) {
99	            return 3;
100	        }
101	        return 4;
102	    }
103	
104	    /**
105	     * The number of owners sharing this owner's {@code householdId} (the persisted household
106	     * key derived from last name and postcode). Returns 1 when no household is on file or the
107	     * repository is unavailable, so the household factor scores nothing in those cases.
108	     */
109	    private long householdSize(Owner owner) {
110	        String householdId = owner.getHouseholdId();
111	        if (householdId == null || ownerRepository == null) {
112	            return 1;
113	        }
114	        long count = 0;
115	        for (Owner existing : ownerRepository.findAll()) {
116	            if (householdId.equals(existing.getHouseholdId())) {
117	                count++;
118	            }
119	        }
120	        return count;
121	    }
122	
123	    /**
124	     * The owner's tenure in whole days, measured from their {@code registrationDate} to
125	     * the current date. Returns 0 when no registrationDate is on file (e.g. a brand-new
126	     * owner before one is assigned), so such an owner has zero tenure.
127	     */
128	    private long tenureDays(Owner owner) {
129	        LocalDate registrationDate = owner.getRegistrationDate();
130	        if (registrationDate == null) {
131	            return 0;
132	        }
133	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
134	    }
135	
136	    /**
137	     * Computes a single Luhn check digit (0-9) over the digits contained in the owner's
138	     * {@code customerCode}. Non-digit characters (separators) are ignored. Returns
139	     * {@code null} when no customer code has been assigned.
140	     */
141	    protected Integer checkDigit(Owner owner) {
142	        String code = owner.getCustomerCode();
143	        if (code == null) {
144	            return null;
145	        }
146	        int sum = 0;
147	        boolean dbl = true;
148	        for (int i = code.length() - 1; i >= 0; i--) {
149	            char c = code.charAt(i);
150	            if (c < '0' || c > '9') {
151	                continue;
152	            }
153	            int d = c - '0';
154	            if (dbl) {
155	                d *= 2;
156	                if (d > 9) {
157	                    d -= 9;
158	                }
159	            }
160	            sum += d;
161	            dbl = !dbl;
162	        }
163	        return (10 - (sum % 10)) % 10;
164	    }
165	
166	    /**
167	     * Derives the owner's {@code locality} from the REGION component of the
168	     * {@code <REGION>-<HASH8>} customer code — the region-and-hash identity is now the single
169	     * source of the owner's region. Falls back to the postcode/city lookup for an owner that has
170	     * no customer code yet (e.g. seed data created outside the create pipeline).
171	     */
172	    protected String locality(Owner owner) {
173	        String code = owner.getCustomerCode();
174	        if (code != null) {
175	            int dash = code.indexOf('-');
176	            return dash >= 0 ? code.substring(0, dash) : code;
177	        }
178	        return LocalityLookup.regionFor(owner.getCity(), owner.getPostcode());
179	    }
180	
181	    /**
182	     * Derives the owner's {@code timezone} as the IANA name for the owner's region, using
183	     * the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
184	     * QLD->Australia/Brisbane). The region is the same {@link #locality(Owner)} value.
185	     * Returns {@code null} when the region has no mapped timezone (e.g. "UNKNOWN"), so the
186	     * field is then absent from the response.
187	     */
188	    protected String timezone(Owner owner) {
189	        return LocalityLookup.timezoneFor(locality(owner));
190	    }
191	
192	    /**
193	     * Derives the owner's preferred contact channel: 'EMAIL' when an email address is
194	     * on file, otherwise 'PHONE'.
195	     */
196	    protected String contactPreference(Owner owner) {
197	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
198	    }
199	
200	    /**
201	     * Derives the owner's age band from their birthDate as of their registrationDate:
202	     * 'MINOR' when under 18, 'ADULT' when 18-64, 'SENIOR' when 65 or over. Returns
203	     * {@code null} when no birthDate is on file (the field is then absent from the
204	     * response). The reference date is the registrationDate, falling back to the current
205	     * date only for legacy owners created without one.
206	     */
207	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
208	        LocalDate birthDate = owner.getBirthDate();
209	        if (birthDate == null) {
210	            return null;
211	        }
212	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
213	        int age = Period.between(birthDate, asOf).getYears();
214	        if (age < 18) {
215	            return OwnerDto.AgeBandEnum.MINOR;
216	        }
217	        if (age < 65) {
218	            return OwnerDto.AgeBandEnum.ADULT;
219	        }
220	        return OwnerDto.AgeBandEnum.SENIOR;
221	    }
222	
223	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
224	        OwnerPageDto ownerPageDto = new OwnerPageDto();
225	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
226	        ownerPageDto.setPage(ownerPage.getNumber());
227	        ownerPageDto.setSize(ownerPage.getSize());
228	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
229	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
230	        return ownerPageDto;
231	    }
