3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single derived identity of an owner used for duplicate detection.
9	 *
10	 * <p>An owner's {@code identityKey} is
11	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
12	 * telephone is its E.164 form, the email is its lower-cased form (empty when absent or
13	 * blank) and the householdId is the owner's shared-household identifier (empty when the
14	 * owner does not share a household). Two owners are duplicates only when their whole
15	 * identity keys are equal — so, for example, two members of the same household (same
16	 * householdId) with different telephones have different keys and are both allowed.
17	 */
18	public final class OwnerIdentityKey {
19	
20	    private OwnerIdentityKey() {
21	    }
22	
23	    /**
24	     * Builds an identity key from its already-normalized parts.
25	     *
26	     * @param telephoneE164 the E.164 telephone (never blank for a valid owner)
27	     * @param email the email, or {@code null}/blank when none
28	     * @param householdId the shared-household id, or {@code null}/empty when none
29	     * @return the {@code telephone|email|householdId} identity key
30	     */
31	    public static String of(String telephoneE164, String email, String householdId) {
32	        String tel = telephoneE164 == null ? "" : telephoneE164;
33	        String mail = (email == null || email.trim().isEmpty()) ? ""
34	                : email.trim().toLowerCase(Locale.ROOT);
35	        String household = (householdId == null || householdId.isEmpty()) ? "" : householdId;
36	        return tel + "|" + mail + "|" + household;
37	    }
38	
39	    /**
40	     * Derives the identity key of a stored owner, normalizing its telephone to E.164 and its
41	     * email to lower case exactly as the create pipeline normalizes an incoming request, so a
42	     * new owner and an existing owner are compared on the same footing.
43	     */
44	    public static String forOwner(Owner owner) {
45	        return of(TelephoneNormalizer.toE164(owner.getTelephone()), owner.getEmail(),
46	                owner.getHouseholdId());
47	    }
48	}
