3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
8	
9	/**
10	 * The duplicate block for a create-owner request. It rejects a create with a 409 in two cases,
11	 * both keyed off the deterministic {@code householdId} resolved by {@link DetermineOwnerHousehold}
12	 * (derived from {@code (lastName, postcode)}):
13	 *
14	 * <ul>
15	 * <li><b>Exact identity duplicate</b> — an existing owner has the same whole
16	 * {@link OwnerIdentityKey identity key} ({@code normalizedTelephone + '|' + email + '|' +
17	 * householdId}). This is always rejected, even for a declared household member.</li>
18	 * <li><b>Household duplicate</b> — an existing owner shares the same {@code householdId} (i.e. the
19	 * same last name and postcode). Because the household is keyed on {@code (lastName, postcode)},
20	 * such an owner is a second member of an existing household and is rejected — <em>unless</em> the
21	 * request opts in with {@code sharesHousehold} true, which bypasses this block so the owner is
22	 * created as a declared household member.</li>
23	 * </ul>
24	 */
25	public class CheckOwnerIdentityUnique {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
28	            OwnerRepository ownerRepository) throws DuplicateOwnerIdentityException {
29	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
30	        String household = householdId.value();
31	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(),
32	                household);
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
35	                throw new DuplicateOwnerIdentityException(identityKey);
36	            }
37	            if (!sharesHousehold && household.equals(existing.getHouseholdId())) {
38	                throw new DuplicateOwnerIdentityException(household);
39	            }
40	        }
41	    }
42	}
